'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './fireflies.css'

export type FirefliesProps = React.ComponentPropsWithoutRef<'div'> & {
    count?: number
    color?: string
    seed?: number
    paused?: boolean
}

const mulberry32 = (seed: number) => () => {
    seed |= 0
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
}

// Little lights wandering on their own paths and glowing softly on and off.
const Fireflies = ({ count = 26, color = '#fde68a', seed = 5, paused = false, className, style, children, ...props }: FirefliesProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const offscreen = useOffscreen(ref)

    const flies = React.useMemo(() => {
        const random = mulberry32(seed)
        const step = () => `${(random() * 120 - 60).toFixed(0)}px`
        return Array.from({ length: count }, () => ({
            left: `${(random() * 100).toFixed(1)}%`,
            top: `${(random() * 100).toFixed(1)}%`,
            path: [step(), step(), step(), step(), step(), step()],
            duration: `${(random() * 10 + 12).toFixed(1)}s`,
            glow: `${(random() * 2 + 2).toFixed(2)}s`,
            delay: `${(random() * -20).toFixed(1)}s`
        }))
    }, [count, seed])

    return <div
        ref={ref}
        className={['rad-fx-fireflies', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ '--rad-fx-firefly-color': color, ...style } as React.CSSProperties}
        {...props}
    >
        <div className="rad-fx-fireflies-air" aria-hidden="true">
            {flies.map((fly, i) => (
                <span
                    key={i}
                    className="rad-fx-firefly"
                    style={{
                        left: fly.left,
                        top: fly.top,
                        animationDuration: `${fly.duration}, ${fly.glow}`,
                        animationDelay: `${fly.delay}, ${fly.delay}`,
                        '--x1': fly.path[0], '--y1': fly.path[1], '--x2': fly.path[2], '--y2': fly.path[3], '--x3': fly.path[4], '--y3': fly.path[5]
                    } as React.CSSProperties}
                />
            ))}
        </div>
        <div className="rad-fx-fireflies-content">{children}</div>
    </div>
}

export default Fireflies

.rad-fx-fireflies {
    position: relative;
    isolation: isolate;
    overflow: hidden;
}

.rad-fx-fireflies-air {
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
}

.rad-fx-firefly {
    position: absolute;
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: var(--rad-fx-firefly-color);
    box-shadow: 0 0 8px 2px var(--rad-fx-firefly-color), 0 0 18px 4px color-mix(in srgb, var(--rad-fx-firefly-color) 40%, transparent);
    animation-name: rad-fx-firefly-wander, rad-fx-firefly-glow;
    animation-timing-function: ease-in-out, ease-in-out;
    animation-iteration-count: infinite, infinite;
    animation-direction: alternate, alternate;
}

.rad-fx-fireflies[data-state='paused'] .rad-fx-firefly { animation-play-state: paused; }

.rad-fx-fireflies-content { position: relative; }

@keyframes rad-fx-firefly-wander {
    0% { transform: translate(0, 0); }
    33% { transform: translate(var(--x1), var(--y1)); }
    66% { transform: translate(var(--x2), var(--y2)); }
    100% { transform: translate(var(--x3), var(--y3)); }
}

@keyframes rad-fx-firefly-glow {
    0%, 30% { opacity: 0.15; }
    100% { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-firefly { animation: none; opacity: 0.7; }
}

[data-rad-fx-motion='reduce'] .rad-fx-firefly { animation: none; opacity: 0.7; }
